/* ============================================================
   Pip, rebuilt in WebGL.

   Same character and the same contract as ./FormCompanion — `stage` 0-4,
   plus waiting / sending / sent — but as real geometry instead of an SVG
   sprite, borrowing the techniques from pages/projects/LilAgents3D: rounded
   primitives with a clearcoat "candy" finish, a rim light in the accent hue,
   a grounded contact shadow, a head that tracks the pointer, and the DOM
   thought bubble portalled out of the canvas through drei's <Html>.

   What it does NOT borrow is the walk engine. Bolt and Pixel roam a strip;
   Pip is a postal creature that stays on its mark and works the letter it is
   holding. So the whole animation budget goes into the letter instead:

     stage 0     empty envelope, flap open, Pip waiting and looking around
     stage 1-3   a line of writing drops onto the letter per completed field,
                 and Pip hops once each time a new one lands
     stage 4     flap seals, wax seal pops on, both arms go up, hearts lit
     sending     the letter lifts overhead and spins
     sent        the letter flies off to the top right and Pip waves it away

   Rendering is the only thing that differs from the SVG build — mood and
   copy are identical, so the two can be swapped with ?pip=2d / ?pip=3d and
   compared directly.
   ============================================================ */
import React, { useEffect, useMemo, useRef, useState } from "react";
import * as THREE from "three";
import { Canvas, useFrame, useThree } from "@react-three/fiber";
import { ContactShadows } from "@react-three/drei";
import "./FormCompanion3D.css";

const prefersReducedMotion = () =>
  typeof window !== "undefined" &&
  window.matchMedia &&
  window.matchMedia("(prefers-reduced-motion: reduce)").matches;

/* Kept identical to the SVG build so the two variants say the same things. */
const IDLE_THOUGHTS = [
  "waiting for you…",
  "tell me anything",
  "I'll pass it straight on ✉️",
  "still here 👀",
  "no rush",
];

const STAGE_THOUGHTS = [
  null, // 0 — handled by the idle cycle
  "got your name!",
  "…and where to reply",
  "ooh, a subject",
  "thank you! 💛",
];

const lerp = (a, b, t) => a + (b - a) * t;
const clamp01 = (v) => Math.min(Math.max(v, 0), 1);
const damp = (cur, target, rate, dt) =>
  lerp(cur, target, 1 - Math.exp(-rate * dt));

/* Distance from Pip's origin down to the soles, so the root can be lifted by
   it and the scene shares a ground plane at y = 0 — same trick as LilAgents3D. */
const FOOT = 0.48;

/* ---------------------------------------------------------------------------
   The heart that pops per completed field. Built once as a shape and shared
   by all four instances; the SVG build uses a ♥ glyph, which has no 3D
   equivalent worth faking with a plane.
   --------------------------------------------------------------------------- */
function useHeartGeometry() {
  return useMemo(() => {
    const s = new THREE.Shape();
    s.moveTo(0.25, 0.25);
    s.bezierCurveTo(0.25, 0.25, 0.2, 0, 0, 0);
    s.bezierCurveTo(-0.3, 0, -0.3, 0.35, -0.3, 0.35);
    s.bezierCurveTo(-0.3, 0.55, -0.1, 0.77, 0.25, 0.95);
    s.bezierCurveTo(0.6, 0.77, 0.8, 0.55, 0.8, 0.35);
    s.bezierCurveTo(0.8, 0.35, 0.8, 0, 0.5, 0);
    s.bezierCurveTo(0.35, 0, 0.25, 0.25, 0.25, 0.25);
    const g = new THREE.ExtrudeGeometry(s, {
      depth: 0.18,
      bevelEnabled: true,
      bevelSize: 0.06,
      bevelThickness: 0.06,
      bevelSegments: 3,
      curveSegments: 12,
    });
    // The shape is drawn point-down-at-origin; centre it and flip so the
    // lobes end up on top, then scale to something Pip can wear.
    g.center();
    g.rotateZ(Math.PI);
    g.scale(0.115, 0.115, 0.115);
    return g;
  }, []);
}

/* Card dimensions, in one place: the flap, the writing lines and the arm
   spread are all derived from them, so the letter can be resized without
   three separate sets of magic numbers drifting apart. */
const CARD_W = 0.38;
const CARD_H = 0.27;
const FLAP_H = 0.145;

/* The envelope flap. A cone with 3 radial segments is the obvious cheat and
   it looks like one — it has depth and catches a specular on each facet. A
   flat ShapeGeometry triangle is what an envelope flap actually is. */
function useFlapGeometry() {
  return useMemo(() => {
    const s = new THREE.Shape();
    s.moveTo(-CARD_W / 2, 0);
    s.lineTo(CARD_W / 2, 0);
    s.lineTo(0, -FLAP_H);
    s.closePath();
    return new THREE.ShapeGeometry(s);
  }, []);
}

/* ---------------------------------------------------------------------------
   The letter. Its own component so the writing lines can be driven straight
   off `stage` without re-rendering Pip.
   --------------------------------------------------------------------------- */
function Letter({ stage, palette, sealRef, flapRef, lineRefs }) {
  const flapGeo = useFlapGeometry();

  return (
    <group>
      {/* card */}
      <mesh>
        <boxGeometry args={[CARD_W, CARD_H, 0.022]} />
        <meshPhysicalMaterial
          color={palette.paper}
          roughness={0.62}
          clearcoat={0.35}
          clearcoatRoughness={0.6}
        />
      </mesh>

      {/* The flap, hinged on the card's top edge: folded back while the form
          is unfinished, laid flat over the front once it is sendable.
          DoubleSide because the open pose shows its back. */}
      <group ref={flapRef} position={[0, CARD_H / 2, 0.013]}>
        <mesh geometry={flapGeo}>
          <meshPhysicalMaterial
            color={palette.paperEdge}
            side={THREE.DoubleSide}
            roughness={0.55}
            clearcoat={0.4}
            clearcoatRoughness={0.55}
          />
        </mesh>
      </group>

      {/* One line of writing per completed field. They are always mounted and
          scaled from zero, so a field going invalid again shrinks its line
          away instead of popping the whole letter. */}
      {[0, 1, 2, 3].map((i) => (
        <mesh
          key={i}
          ref={lineRefs[i]}
          position={[-0.035 + i * 0.013, 0.079 - i * 0.055, 0.012]}
          scale={[stage > i ? 1 : 0.001, 1, 1]}
        >
          <boxGeometry args={[0.22 - i * 0.026, 0.019, 0.005]} />
          <meshStandardMaterial
            color={palette.ink}
            roughness={0.5}
            transparent
            opacity={0.75}
          />
        </mesh>
      ))}

      {/* Wax seal — it sits on the flap's point, so it only makes sense once
          the flap is down, which is why it pops in on stage 4. */}
      <mesh
        ref={sealRef}
        position={[0, CARD_H / 2 - FLAP_H, 0.024]}
        rotation={[Math.PI / 2, 0, 0]}
        scale={0.001}
      >
        <cylinderGeometry args={[0.07, 0.07, 0.022, 20]} />
        <meshPhysicalMaterial
          color={palette.accent2}
          emissive={palette.accent2}
          emissiveIntensity={0.35}
          roughness={0.3}
          clearcoat={1}
          clearcoatRoughness={0.25}
        />
      </mesh>
    </group>
  );
}

/* ---------------------------------------------------------------------------
   Pip
   --------------------------------------------------------------------------- */
function Pip({ stage, mood, palette, frozen, pointer }) {
  const root = useRef();
  const body = useRef();
  const head = useRef();
  const armL = useRef();
  const armR = useRef();
  const eyes = useRef();
  const smile = useRef();
  const letter = useRef();
  const seal = useRef();
  const flap = useRef();
  const hearts = useRef([useRef(), useRef(), useRef(), useRef()]).current;
  const lineRefs = useRef([useRef(), useRef(), useRef(), useRef()]).current;
  const pupils = useRef([useRef(), useRef()]).current;
  const antenna = useRef();

  const heartGeo = useHeartGeometry();

  /* Everything the frame loop needs that must not cause a re-render: the hop
     trigger, the send clock, and the last stage we saw. */
  const st = useRef({
    prevStage: stage,
    hopAt: -10,
    sendAt: -10,
    prevMood: mood,
    look: 0,
    lookAt: 0,
  }).current;

  const skin = useMemo(
    () => ({
      color: palette.body,
      roughness: 0.28,
      metalness: 0,
      clearcoat: 1,
      clearcoatRoughness: 0.3,
      emissive: palette.bodyDeep,
      emissiveIntensity: 0.14,
    }),
    [palette.body, palette.bodyDeep]
  );

  useFrame((state, delta) => {
    if (!root.current) return;
    const t = state.clock.getElapsedTime();
    const dt = Math.min(delta, 0.05);

    /* --- edges ------------------------------------------------------------
       A field landing is a one-frame event, so it is latched here rather than
       in an effect: the loop already has the clock, and an effect would need
       its own timer to expire the hop. */
    if (stage !== st.prevStage) {
      if (stage > st.prevStage) st.hopAt = t;
      st.prevStage = stage;
    }
    if (mood !== st.prevMood) {
      if (mood === "sent") st.sendAt = t;
      st.prevMood = mood;
    }

    const sending = mood === "sending";
    const sent = mood === "sent";
    const happy = mood === "happy";

    if (frozen) {
      root.current.position.set(0, FOOT, 0);
      return;
    }

    /* --- bob --------------------------------------------------------------
       Base breathing, plus a decaying hop whenever a field lands. The hop is
       a half sine over 0.42s so it lands back on the ground rather than
       easing out in mid-air. */
    const hopT = clamp01((t - st.hopAt) / 0.42);
    const hop = st.hopAt > 0 && hopT < 1 ? Math.sin(hopT * Math.PI) * 0.13 : 0;
    const breathe = Math.sin(t * 1.9) * 0.018;
    const excited = happy || sending ? Math.abs(Math.sin(t * 4.2)) * 0.035 : 0;
    root.current.position.y = FOOT + breathe + hop + excited;
    root.current.position.x = 0;

    // A small squash on landing sells the weight
    if (body.current) {
      const squash = hopT < 1 && st.hopAt > 0 ? Math.sin(hopT * Math.PI) : 0;
      body.current.scale.y = damp(
        body.current.scale.y,
        1 + squash * 0.06,
        14,
        dt
      );
      body.current.scale.x = damp(
        body.current.scale.x,
        1 - squash * 0.04,
        14,
        dt
      );
    }

    /* --- head -------------------------------------------------------------
       Tracks the pointer, like the bots do. While idle it also drifts to a new
       random spot every few seconds, which is what makes "waiting" read as
       waiting rather than as staring. */
    if (head.current) {
      if (mood === "waiting" && t > st.lookAt) {
        st.look = (Math.random() - 0.5) * 0.7;
        st.lookAt = t + 1.8 + Math.random() * 2.4;
      }
      const tracking = pointer.active;
      const yTarget = sent
        ? 0.55 // watching the letter go
        : sending
        ? 0
        : tracking
        ? pointer.x * 0.45
        : st.look;
      const xTarget = sent
        ? -0.32
        : sending
        ? -0.2
        : tracking
        ? pointer.y * 0.34
        : 0;
      head.current.rotation.y = damp(head.current.rotation.y, yTarget, 4, dt);
      head.current.rotation.x = damp(head.current.rotation.x, xTarget, 4, dt);
      head.current.rotation.z = damp(
        head.current.rotation.z,
        mood === "cheer" ? 0.12 : 0,
        5,
        dt
      );
    }

    /* --- pupils -----------------------------------------------------------
       The head turn alone is too coarse to read as "looking at you" at this
       size, so the pupils slide inside the whites on top of it — the same
       thing the SVG build does with --eye-x / --eye-y. The travel is small
       and clamped: push it any further and the pupils leave the white and
       Pip goes cross-eyed. */
    pupils.forEach((r) => {
      if (!r.current) return;
      const look = sent ? { x: 0.9, y: -0.9 } : pointer;
      r.current.position.x = damp(r.current.position.x, look.x * 0.034, 9, dt);
      r.current.position.y = damp(r.current.position.y, look.y * -0.046, 9, dt);
    });

    /* --- blink ------------------------------------------------------------ */
    if (eyes.current) {
      const b = t % 3.9;
      const shut = b < 0.12;
      eyes.current.scale.y = shut ? 0.08 : 1;
      eyes.current.position.y = shut ? 0.028 : 0;
    }

    /* --- mouth ------------------------------------------------------------
       One mesh, widened rather than swapped: a small o while empty, a broad
       smile once the message is complete. */
    if (smile.current) {
      const wide = sent || happy ? 1.5 : stage > 0 ? 1.15 : 0.72;
      smile.current.scale.x = damp(smile.current.scale.x, wide, 8, dt);
      smile.current.scale.y = damp(
        smile.current.scale.y,
        sent || happy ? 1.25 : 0.85,
        8,
        dt
      );
    }

    /* --- arms + letter ----------------------------------------------------
       Three poses: holding the letter out front, holding it overhead while
       sending, and waving after it has gone. */
    const sendT = clamp01((t - st.sendAt) / 1.15);

    if (letter.current) {
      if (sent && st.sendAt > 0) {
        // Flies off to the top right, tumbling, and shrinks into the distance
        const e = sendT * sendT;
        letter.current.position.set(
          lerp(0, 1.3, e),
          lerp(1.0, 2.0, e),
          lerp(0.2, -0.9, e)
        );
        letter.current.rotation.set(
          -0.2 + sendT * 1.1,
          sendT * 2.6,
          -sendT * 1.4
        );
        letter.current.scale.setScalar(Math.max(0.001, 1 - sendT * 0.9));
      } else if (sending) {
        letter.current.position.x = damp(letter.current.position.x, 0, 7, dt);
        letter.current.position.y = damp(letter.current.position.y, 1.0, 7, dt);
        letter.current.position.z = damp(letter.current.position.z, 0.2, 7, dt);
        letter.current.rotation.y += dt * 2.4;
        letter.current.rotation.x = damp(
          letter.current.rotation.x,
          -0.1,
          7,
          dt
        );
        letter.current.rotation.z = 0;
        letter.current.scale.setScalar(damp(letter.current.scale.x, 1, 9, dt));
      } else {
        letter.current.position.x = damp(letter.current.position.x, 0, 7, dt);
        letter.current.position.y = damp(
          letter.current.position.y,
          -0.09,
          7,
          dt
        );
        letter.current.position.z = damp(letter.current.position.z, 0.4, 7, dt);
        letter.current.rotation.x = damp(
          letter.current.rotation.x,
          -0.3,
          7,
          dt
        );
        letter.current.rotation.y = damp(letter.current.rotation.y, 0, 7, dt);
        letter.current.rotation.z = damp(
          letter.current.rotation.z,
          Math.sin(t * 1.4) * 0.05,
          6,
          dt
        );
        letter.current.scale.setScalar(damp(letter.current.scale.x, 1, 9, dt));
      }
    }

    // Flap: folded back while unfinished, sealed flat once sendable
    if (flap.current) {
      flap.current.rotation.x = damp(
        flap.current.rotation.x,
        stage >= 4 ? 0 : -2.35,
        7,
        dt
      );
    }
    // The seal presses on rather than growing: it overshoots past 1 and
    // settles back, which is the difference between "stamped" and "inflated".
    if (seal.current) {
      const on = stage >= 4;
      const settle = on ? 1 : 0.001;
      const over = on ? 1.35 : 0.001;
      const cur = seal.current.scale.x;
      seal.current.scale.setScalar(
        cur < settle * 0.98 ? damp(cur, over, 16, dt) : damp(cur, settle, 9, dt)
      );
    }

    // Writing lines grow in from the left as their field validates
    lineRefs.forEach((r, i) => {
      if (!r.current) return;
      r.current.scale.x = damp(
        r.current.scale.x,
        stage > i ? 1 : 0.001,
        10,
        dt
      );
    });

    if (armL.current && armR.current) {
      const up = sending ? -1.9 : sent ? -0.5 : happy ? -1.3 : -1.05;
      const wave = sent ? Math.sin(t * 9) * 0.35 : 0;
      armL.current.rotation.x = damp(armL.current.rotation.x, up, 8, dt);
      armR.current.rotation.x = damp(
        armR.current.rotation.x,
        sent ? -0.2 : up,
        8,
        dt
      );
      armL.current.rotation.z = damp(
        armL.current.rotation.z,
        sending ? 0.4 : 0.3,
        8,
        dt
      );
      armR.current.rotation.z = damp(
        armR.current.rotation.z,
        sent ? -1.5 + wave : sending ? -0.4 : -0.3,
        sent ? 20 : 8,
        dt
      );
    }

    /* --- hearts + antenna -------------------------------------------------
       One heart per completed field, popping in with a spin and then hovering
       on its own phase so the row never looks like a progress bar. */
    hearts.forEach((r, i) => {
      if (!r.current) return;
      const on = stage > i;
      const target = on ? 1 : 0.001;
      r.current.scale.setScalar(damp(r.current.scale.x, target, 12, dt));
      if (on) {
        r.current.position.y = 1.3 + Math.sin(t * 2.6 + i * 1.5) * 0.05;
        r.current.rotation.z = Math.sin(t * 1.8 + i) * 0.28;
      }
    });

    if (antenna.current) {
      const pulse = 1 + Math.sin(t * (sending ? 9 : 3)) * 0.2;
      antenna.current.scale.setScalar(pulse);
    }
  });

  return (
    <group ref={root} position={[0, FOOT, 0]}>
      <group ref={body}>
        {/* Torso — kept under half the head's width; the head-to-body ratio is
            where the cuteness lives, same as the bots. */}
        <mesh position={[0, 0, 0]} scale={[1, 0.98, 0.9]}>
          <sphereGeometry args={[0.34, 30, 30]} />
          <meshPhysicalMaterial {...skin} />
        </mesh>

        {/* Courier strap across the chest, so Pip reads as postal and not as
            a generic blob. */}
        <mesh position={[0, 0.02, 0.02]} rotation={[0, 0, -0.62]}>
          <torusGeometry args={[0.315, 0.026, 10, 40]} />
          <meshStandardMaterial
            color={palette.accent}
            roughness={0.45}
            emissive={palette.accent}
            emissiveIntensity={0.18}
          />
        </mesh>

        {/* Satchel on the hip */}
        <group position={[0.3, -0.16, 0.06]} rotation={[0, -0.3, 0]}>
          <mesh>
            <boxGeometry args={[0.17, 0.145, 0.11]} />
            <meshPhysicalMaterial
              color={palette.accent}
              roughness={0.4}
              clearcoat={0.8}
              clearcoatRoughness={0.4}
            />
          </mesh>
          <mesh position={[0, 0.065, 0.008]}>
            <boxGeometry args={[0.175, 0.05, 0.115]} />
            <meshStandardMaterial color={palette.accent2} roughness={0.45} />
          </mesh>
        </group>

        {/* Stubby legs, wide stance */}
        {[-1, 1].map((s) => (
          <mesh
            key={`leg${s}`}
            position={[s * 0.14, -0.35, 0]}
            scale={[0.85, 1.15, 0.85]}
          >
            <sphereGeometry args={[0.11, 18, 18]} />
            <meshPhysicalMaterial
              color={palette.bodyDeep}
              roughness={0.34}
              clearcoat={1}
              clearcoatRoughness={0.38}
            />
          </mesh>
        ))}

        {/* Arms. Pivot at the shoulder so a rotation swings the whole limb —
            the letter is parented separately, so the pose and the letter can
            be timed independently. */}
        <group ref={armL} position={[-0.32, 0.08, 0.02]}>
          <mesh position={[0, -0.14, 0]} scale={[0.8, 1.3, 0.8]}>
            <sphereGeometry args={[0.105, 20, 20]} />
            <meshPhysicalMaterial
              color={palette.bodyLight}
              roughness={0.3}
              clearcoat={1}
              clearcoatRoughness={0.35}
            />
          </mesh>
        </group>
        <group ref={armR} position={[0.32, 0.08, 0.02]}>
          <mesh position={[0, -0.14, 0]} scale={[0.8, 1.3, 0.8]}>
            <sphereGeometry args={[0.105, 20, 20]} />
            <meshPhysicalMaterial
              color={palette.bodyLight}
              roughness={0.3}
              clearcoat={1}
              clearcoatRoughness={0.35}
            />
          </mesh>
        </group>

        {/* Head */}
        <group ref={head} position={[0, 0.46, 0]}>
          {/* One continuous ellipsoid at high segment count — a RoundedBox
              keeps a flat on each face and the clearcoat glares off it as a
              hard rectangular streak. */}
          <mesh scale={[0.5, 0.44, 0.4]}>
            <sphereGeometry args={[1, 48, 36]} />
            <meshPhysicalMaterial {...skin} />
          </mesh>

          {/* Postal cap: crown plus a brim over the brow. This is the one
              piece of costume that separates Pip from Bolt and Pixel at a
              glance. */}
          <group position={[0, 0.3, -0.02]} rotation={[-0.16, 0, 0]}>
            <mesh position={[0, 0.05, 0]} scale={[1, 0.55, 0.92]}>
              <sphereGeometry
                args={[0.36, 28, 20, 0, Math.PI * 2, 0, Math.PI / 2]}
              />
              <meshPhysicalMaterial
                color={palette.accent}
                roughness={0.4}
                clearcoat={1}
                clearcoatRoughness={0.35}
              />
            </mesh>
            <mesh
              position={[0, 0.02, 0.14]}
              rotation={[0.26, 0, 0]}
              scale={[1, 0.14, 1]}
            >
              <cylinderGeometry
                args={[0.3, 0.3, 0.1, 28, 1, false, -Math.PI / 2, Math.PI]}
              />
              <meshPhysicalMaterial
                color={palette.accent2}
                roughness={0.42}
                clearcoat={1}
                clearcoatRoughness={0.35}
              />
            </mesh>
          </group>

          {/* Pale muzzle across the lower face. It has to actually clear the
              head's own surface at that height or it renders as nothing at
              all — but it must stay *below* the eyes, or it renders over
              them and Pip loses his face entirely. Hence a wide, shallow
              ellipsoid low on the head rather than a full face plate. */}
          <mesh position={[0, -0.16, 0.28]} scale={[0.72, 0.36, 0.3]}>
            <sphereGeometry args={[0.4, 32, 32]} />
            <meshPhysicalMaterial
              color={palette.faceLight}
              roughness={0.36}
              clearcoat={1}
              clearcoatRoughness={0.34}
            />
          </mesh>

          {/* Eyes */}
          <group ref={eyes}>
            {[-1, 1].map((s, i) => (
              <group key={s}>
                <mesh
                  position={[s * 0.155, 0.03, 0.33]}
                  scale={[1, 1.15, 0.32]}
                >
                  <sphereGeometry args={[0.105, 24, 24]} />
                  <meshStandardMaterial color="#ffffff" roughness={0.5} />
                </mesh>
                {/* pupil and its catchlight move together, or the highlight
                    slides off the pupil as it tracks */}
                <group ref={pupils[i]}>
                  <mesh
                    position={[s * 0.155, 0.03, 0.352]}
                    scale={[1, 1.1, 0.46]}
                  >
                    <sphereGeometry args={[0.07, 24, 24]} />
                    <meshStandardMaterial
                      color="#16162b"
                      roughness={0.14}
                      metalness={0.1}
                    />
                  </mesh>
                  <mesh position={[s * 0.172, 0.063, 0.385]}>
                    <sphereGeometry args={[0.021, 14, 14]} />
                    <meshStandardMaterial
                      color="#ffffff"
                      emissive="#ffffff"
                      emissiveIntensity={1.4}
                      toneMapped={false}
                    />
                  </mesh>
                </group>
              </group>
            ))}
          </group>

          {/* Mouth — scaled by the loop rather than swapped */}
          <mesh
            ref={smile}
            position={[0, -0.14, 0.415]}
            rotation={[0, 0, Math.PI]}
          >
            <torusGeometry args={[0.062, 0.011, 10, 22, Math.PI * 0.9]} />
            <meshStandardMaterial color="#16162b" roughness={0.4} />
          </mesh>

          {/* Blush */}
          {[-1, 1].map((s) => (
            <mesh
              key={`bl${s}`}
              position={[s * 0.34, -0.08, 0.26]}
              scale={[1, 0.66, 0.2]}
            >
              <sphereGeometry args={[0.085, 18, 18]} />
              <meshBasicMaterial
                color={palette.accent2}
                transparent
                opacity={0.5}
                toneMapped={false}
              />
            </mesh>
          ))}

          {/* Antenna — the "I'm listening" tell, and it beats faster while
              the message is in flight. */}
          <mesh position={[0, 0.5, -0.06]}>
            <cylinderGeometry args={[0.012, 0.012, 0.18, 8]} />
            <meshStandardMaterial color={palette.bodyDeep} roughness={0.7} />
          </mesh>
          <mesh ref={antenna} position={[0, 0.585, -0.06]}>
            <sphereGeometry args={[0.05, 16, 16]} />
            <meshStandardMaterial
              color={palette.accent}
              emissive={palette.accent}
              emissiveIntensity={2.2}
              toneMapped={false}
            />
          </mesh>
        </group>
      </group>

      {/* The letter rides outside <body> so the squash on landing does not
          also squash the paper. */}
      <group ref={letter} position={[0, -0.09, 0.4]} rotation={[-0.34, 0, 0]}>
        <Letter
          stage={stage}
          palette={palette}
          sealRef={seal}
          flapRef={flap}
          lineRefs={lineRefs}
        />
      </group>

      {/* One heart per completed field */}
      {[0, 1, 2, 3].map((i) => (
        <mesh
          key={i}
          ref={hearts[i]}
          geometry={heartGeo}
          position={[-0.42 + i * 0.28, 1.3, -0.1]}
          scale={0.001}
        >
          <meshStandardMaterial
            color={palette.accent2}
            emissive={palette.accent2}
            emissiveIntensity={0.7}
            roughness={0.3}
            toneMapped={false}
          />
        </mesh>
      ))}

      {/* Key fill in front plus a rim behind in the accent hue — the rim is
          what lights the silhouette edges brighter than the interior, which
          is the trick that sells the jelly read. */}
      <pointLight
        position={[0, 0.8, 2]}
        distance={5}
        intensity={0.3}
        color={palette.accent}
      />
      <pointLight
        position={[0, 1, -1.4]}
        distance={4}
        intensity={0.75}
        color={palette.accent2}
      />
    </group>
  );
}

/* ---------------------------------------------------------------------------
   Camera rig — pins the ground plane (y = 0) to the bottom edge of the canvas
   so Pip stands on whatever sits below. Computed from the live frustum rather
   than hard-coded, because R3F only applies the <Canvas camera> prop at mount
   and the value has to survive resizes. Straight port from LilAgents3D.
   --------------------------------------------------------------------------- */
const GROUND_MARGIN = 0.06;
const VIEW_HEIGHT = 2.0;
const CAM_DIST = 12;

function CameraRig() {
  const camera = useThree((s) => s.camera);
  const size = useThree((s) => s.size);

  useEffect(() => {
    camera.fov = 2 * Math.atan(VIEW_HEIGHT / 2 / CAM_DIST) * (180 / Math.PI);
    camera.position.set(0, VIEW_HEIGHT / 2 - GROUND_MARGIN, CAM_DIST);
    // R3F aims the default camera at the origin, which pitches it down and
    // breaks the flat-frustum maths above. Level it back out.
    camera.rotation.set(0, 0, 0);
    camera.near = 0.1;
    camera.far = 60;
    camera.updateProjectionMatrix();
    camera.updateMatrixWorld();
  }, [camera, size.width, size.height]);

  return null;
}

/* ---------------------------------------------------------------------------
   Wrapper — same props as ./FormCompanion, so the two are drop-in swappable.
   --------------------------------------------------------------------------- */
export default function FormCompanion3D({ stage, waiting, sending, sent }) {
  const hostRef = useRef(null);
  const [visible, setVisible] = useState(true);
  const [idleIdx, setIdleIdx] = useState(0);
  const frozen = prefersReducedMotion();

  const ready = stage >= 4;

  /* The scene's colours come from the page, not from a second palette that
     would then have to be kept in sync with the theme. Read once from the
     host element's computed style — three.js cannot resolve a CSS custom
     property itself. */
  const [palette, setPalette] = useState(null);
  useEffect(() => {
    const el = hostRef.current;
    if (!el) return;
    const cs = getComputedStyle(el);
    const get = (name, fallback) => {
      const v = cs.getPropertyValue(name).trim();
      return v || fallback;
    };
    const accent = get("--accent", "#ffc107");
    const accent2 = get("--accent2", "#f56565");
    const fg = get("--fg", "#f7fafc");
    const bg = get("--bg", "#252827");

    // Mix towards the page's own foreground/background so Pip sits in the
    // page's light rather than glowing on top of it.
    const mix = (a, b, t) => {
      const c1 = new THREE.Color(a);
      const c2 = new THREE.Color(b);
      return `#${c1.lerp(c2, t).getHexString()}`;
    };

    setPalette({
      accent,
      accent2,
      body: mix(mix(bg, fg, 0.46), accent, 0.1),
      bodyLight: mix(mix(bg, fg, 0.58), accent, 0.12),
      bodyDeep: mix(bg, accent, 0.3),
      faceLight: mix(bg, fg, 0.72),
      paper: mix(mix(fg, "#ffffff", 0.4), accent, 0.16),
      paperEdge: mix(mix(fg, "#ffffff", 0.1), accent, 0.5),
      ink: mix(bg, fg, 0.15),
    });
  }, []);

  /* Where the cursor is, relative to Pip, as a direction in -1..1.

     R3F's own state.mouse only updates from pointer events on the canvas —
     and the canvas is both tiny and pointer-events:none, so it would never
     fire. This is the SVG build's trick instead: one rAF-batched window
     listener writing into a mutable ref, never into React state, so the
     tracking costs nothing per render. */
  const pointer = useRef({ x: 0, y: 0, active: false }).current;
  useEffect(() => {
    if (frozen) return undefined;
    if (window.matchMedia && !window.matchMedia("(pointer: fine)").matches)
      return undefined;
    const el = hostRef.current;
    if (!el) return undefined;
    let raf = null;
    const onMove = (e) => {
      if (raf) return;
      raf = requestAnimationFrame(() => {
        raf = null;
        const r = el.getBoundingClientRect();
        // Each axis saturates against its OWN extent. Normalising both by
        // max(width, height) meant the vertical was divided by the window's
        // *width* — on any landscape viewport that squeezed the up/down range
        // down to a fraction of the left/right one, which is why Pip barely
        // looked up or down. Vertical gets the tighter fraction of the two,
        // because there is simply less page above and below him than beside.
        const spanX = window.innerWidth * 0.34;
        const spanY = window.innerHeight * 0.28;
        const cx = (e.clientX - (r.left + r.width / 2)) / spanX;
        const cy = (e.clientY - (r.top + r.height / 2)) / spanY;
        pointer.x = Math.max(-1, Math.min(1, cx));
        pointer.y = Math.max(-1, Math.min(1, cy));
        pointer.active = true;
      });
    };
    window.addEventListener("mousemove", onMove, { passive: true });
    return () => {
      window.removeEventListener("mousemove", onMove);
      if (raf) cancelAnimationFrame(raf);
    };
  }, [frozen, pointer]);

  /* Only render frames while Pip is on screen */
  useEffect(() => {
    const el = hostRef.current;
    if (!el || typeof IntersectionObserver === "undefined") return;
    const io = new IntersectionObserver(([e]) => setVisible(e.isIntersecting), {
      rootMargin: "120px",
    });
    io.observe(el);
    return () => io.disconnect();
  }, []);

  /* Idle thoughts only advance while Pip is actually idle, so they are not
     quietly cycling behind a visitor who is mid-sentence. */
  useEffect(() => {
    if (!waiting || stage > 0) return undefined;
    const id = setInterval(
      () => setIdleIdx((i) => (i + 1) % IDLE_THOUGHTS.length),
      3800
    );
    return () => clearInterval(id);
  }, [waiting, stage]);

  let mood = "idle";
  if (sent) mood = "sent";
  else if (sending) mood = "sending";
  else if (ready) mood = "happy";
  else if (stage > 0) mood = "cheer";
  else if (waiting) mood = "waiting";

  let thought = null;
  if (sent) thought = "off it goes! 🕊️";
  else if (sending) thought = "sending…";
  else if (stage > 0) thought = STAGE_THOUGHTS[Math.min(stage, 4)];
  else if (waiting) thought = IDLE_THOUGHTS[idleIdx];

  return (
    <div className="pip3" data-mood={mood} ref={hostRef} aria-hidden="true">
      {/* The thought sits in the DOM rather than in the scene: it is text, it
          has to reflow, and the progress rail below already announces the
          same state to a screen reader — hence aria-hidden on the wrapper. */}
      <div className="pip3-bubble" data-shown={thought ? "1" : "0"}>
        <span key={thought}>{thought}</span>
      </div>

      <div className="pip3-stage">
        {palette && (
          <Canvas
            dpr={[1, 2]}
            frameloop={visible && !frozen ? "always" : "demand"}
            camera={{
              position: [0, 0.94, CAM_DIST],
              fov: 9.5,
              near: 0.1,
              far: 60,
            }}
            gl={{ antialias: true, alpha: true }}
          >
            <CameraRig />
            <ambientLight intensity={0.55} />
            {/* Key from the upper left, where the specular sweep should sit */}
            <directionalLight position={[-3, 4, 4]} intensity={1.1} />
            {/* Cool back rim, to separate Pip from the page behind */}
            <directionalLight
              position={[2, 3, -4]}
              intensity={0.55}
              color="#bcd4ff"
            />
            {/* Bounce off the surface below */}
            <directionalLight position={[0, -3, 2]} intensity={0.22} />

            <Pip
              stage={stage}
              mood={mood}
              palette={palette}
              frozen={frozen}
              pointer={pointer}
            />

            <ContactShadows
              position={[0, 0.012, 0]}
              opacity={0.4}
              width={4}
              height={3}
              blur={2.2}
              far={2}
              resolution={512}
            />
          </Canvas>
        )}
      </div>
    </div>
  );
}
